import * as E from './engine.js';
const app=document.querySelector('#app');let g=null,screen='home',bike='gravel',selected=0,zoom=1,modal='',message='',auto=localStorage.getItem('velo-auto')!=='false';
try{g=JSON.parse(localStorage.getItem('velo-save'));if(g?.version!==1)g=null;}catch{}
const btn=(text,action,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
function tile(t){let c=E.terrains[t.type],r=E.roads(t);return `<svg viewBox="0 0 90 90" aria-label="${c.name}"><rect width="90" height="90" rx="7" fill="${c.color}"/><path d="M5 15 Q25 0 40 16 T85 10 M0 78 Q30 55 48 76 T90 72" fill="none" stroke="#ffffff25" stroke-width="12"/>${r.map(d=>`<path d="M45 45 L${[[45,0],[90,45],[45,90],[0,45]][d].join(' ')}" stroke="#7e7658" stroke-width="15"/><path d="M45 45 L${[[45,0],[90,45],[45,90],[0,45]][d].join(' ')}" stroke="#f7e7bd" stroke-width="10"/>`).join('')}<circle cx="45" cy="45" r="7" fill="#f7e7bd"/><text x="${r.includes(0)?10:31}" y="28" font-size="23">${c.icon}</text></svg>`;}
function save(){if(g&&auto)try{localStorage.setItem('velo-save',JSON.stringify(g));}catch{message='La sauvegarde est indisponible dans ce navigateur.';}}
function render(){let scroll=document.querySelector('.map'),sx=scroll?.scrollLeft,sy=scroll?.scrollTop;app.innerHTML=`<header><b>🚲 L’Aventure à Vélo</b><div>${btn('Règles','rules','light')} ${screen==='game'?btn('☰','home','light'):''}</div></header>`+(screen==='game'&&g?game():home())+overlay();bind();if(scroll){let m=document.querySelector('.map');if(m){m.scrollLeft=sx;m.scrollTop=sy;}}save();}
function home(){return `<main class="home"><section><div class="eyebrow">EXPLORATION • STRATÉGIE • LIBERTÉ</div><h1>Le voyage<br>se construit<br>en chemin.</h1><p class="sub">Une tuile, une rencontre, un nouveau paysage.<br>Compose ton itinéraire et pars à l’aventure.</p>${screen==='select'?`<div class="choices"><div class="choice ${bike==='gravel'?'selected':''}" data-bike="gravel"><h3>🚴 Gravel</h3><p>Montagnes et cols : coût réduit de 1 énergie.</p></div><div class="choice ${bike==='randonneur'?'selected':''}" data-bike="randonneur"><h3>🚲 Randonneur</h3><p>Départ avec 5 provisions au lieu de 3.</p></div></div>${btn('Commencer le voyage →','start')}`:`${btn('Nouvelle aventure →','new')} ${g?btn('Reprendre','continue','light'):''}<p style="margin-top:14px">${btn('Paramètres','settings','light')}</p>`}<p class="footer">SOLO • 48 TUILES • SAUVEGARDE SUR CET APPAREIL</p></section><div class="hero"><span class="sun">☀️</span><span>🚴</span></div></main>`;}
function game(){E.rescueHand(g);let tiles=Object.values(g.board),s=g.phase==='place'&&g.hand[selected]?E.spots(g,g.hand[selected]):[],all=[...tiles,...s],minX=Math.min(...all.map(t=>t.x))-1,minY=Math.min(...all.map(t=>t.y))-1,maxX=Math.max(...all.map(t=>t.x))+1,maxY=Math.max(...all.map(t=>t.y))+1,size=94*zoom,reachable=E.moves(g);return `<main class="game"><div class="topbar"><div><span class="eyebrow">CARNET DE VOYAGE</span><h2 style="margin:5px 0">Étape ${g.turn} <small class="muted">${tiles.length}/48 tuiles</small></h2></div><div class="stats">${[['⚡','Énergie',g.energy+'/10'],['🍎','Provisions',g.food],['🪙','Argent',g.money],['✨','Aventure',g.points]].map(([i,n,v])=>`<div class="stat">${i} ${n}<strong>${v}</strong></div>`).join('')}</div></div><div class="hint">${g.done?'Votre voyage est terminé.':g.phase==='place'?'1 · Choisis une tuile, tourne-la et touche un emplacement +.':g.phase==='move'?'2 · Touche une tuile voisine dorée pour rouler.':'3 · Une rencontre vous attend.'}</div><div class="layout"><section><div class="map-wrap"><div class="map"><div class="world" style="width:${(maxX-minX+1)*size}px;height:${(maxY-minY+1)*size}px">${tiles.map(t=>`<div class="tile ${g.phase==='move'&&reachable.includes(t)?'reachable':''}" data-move="${E.key(t.x,t.y)}" style="left:${(t.x-minX)*size}px;top:${(t.y-minY)*size}px;width:${90*zoom}px;height:${90*zoom}px">${tile(t)}<label>${E.terrains[t.type].name}</label>${g.pos===E.key(t.x,t.y)?'<span class="rider">🚴</span>':''}</div>`).join('')}${s.map(t=>`<button class="spot" data-place="${t.x},${t.y}" style="left:${(t.x-minX)*size}px;top:${(t.y-minY)*size}px;width:${90*zoom}px;height:${90*zoom}px">+</button>`).join('')}</div></div><div class="maptools">${btn('−','zoomout')}${btn('+','zoomin')}${btn('◎','center')}</div></div><div class="hand">${g.hand.map((t,i)=>`<button data-select="${i}" class="${i===selected?'active':''}" ${g.phase!=='place'?'disabled':''}>${tile(t)}<small>${E.terrains[t.type].name}</small></button>`).join('')}${btn('↻ Tourner','rotate','light')}</div><div class="toast" role="status">${message}</div></section><aside class="panel"><h3>La pause du cycliste</h3><p class="muted">${E.terrains[g.board[g.pos].type].name} · ${g.bike==='gravel'?'Gravel':'Randonneur'}</p><div class="actions">${btn('🍎 Manger · +'+(g.items.includes('rechaud')?5:3)+' énergie','eat')}${btn('⛺ Bivouac · +'+(g.items.includes('tente')?4:2),'rest')}${g.board[g.pos].type==='ville'?btn('🥖 2 provisions · 1 pièce','food')+btn('🔧 Travailler · +2 pièces','work')+btn('🎒 Équipements','shop'):''}${['ville','camping','auberge'].includes(g.board[g.pos].type)?btn('🛏 Dormir · 1 pièce','sleep'):''}${btn('Finir l’étape sans rouler','skip')}${btn('Terminer le voyage','finish')}</div><h4>Journal de route</h4><div class="log">${g.log.map(l=>`<div>• ${l}</div>`).join('')}</div><p class="muted">${g.visited.length-1} nouvelles étapes · ${g.cols} cols<br>${g.items.map(i=>E.equipment[i].name).join(' · ')||'Aucun équipement'}</p></aside></div></main>`;}
function overlay(){let content='';if(g?.event&&screen==='game')content=`<span class="event-icon">${E.terrains[g.board[g.pos].type].icon}</span><span class="eyebrow">CARTE AVENTURE</span><h2>${g.event.title}</h2><p>${g.event.text}</p><p>${g.items.includes(g.event.protect)?'Votre équipement annule la pénalité.':Object.entries(g.event.effect).map(([k,v])=>`${v>0?'+':''}${v} ${{energy:'énergie',food:'provision',money:'argent',points:'points Aventure'}[k]}`).join(' · ')}</p>${btn('Reprendre la route →','resolve')}`;else if(g?.done&&screen==='game')content=`<span class="event-icon">🏆</span><h2>Un voyage à raconter.</h2><h1>${E.score(g)} <small style="font-size:20px">points</small></h1><p>${g.points} points Aventure · ${g.discoveries} découvertes · ${g.cols} cols · ${g.cities} villes · ${g.visited.length-1} étapes inédites.</p><p class="muted">Score = Aventure + découvertes × 3 + cols × 2 + villes + étapes inédites. ${g.steps} déplacements effectués.</p>${btn('Retour à l’accueil','home')}`;else if(modal==='rules')content=`<h2>Prendre la route</h2><p>Pose une tuile à chaque tour. Les routes doivent correspondre à tous les voisins. Tourne ta tuile pour trouver un passage.</p><p>Déplace-toi ensuite d’une seule case par une route connectée, ou termine l’étape sur place. Plaine, ville et côte coûtent 1 énergie ; montagne 2 ; col 3. Le gravel réduit les coûts en montagne de 1.</p><p>Mange ou bivouaque pour récupérer. En ville, achète des provisions, travaille ou équipe ton vélo. Les pauses et services sont libres dans ce prototype.</p><p>Chaque lieu rapporte des points une seule fois. Les événements concernent uniquement les premières visites. La partie se termine après la pose des 48 tuiles et la dernière étape, ou avec « Terminer le voyage ».</p><p>Fais glisser la carte pour l’explorer. Les boutons + et − règlent le zoom. Une main bloquée reçoit une tuile de secours adaptée au réseau.</p>${btn('C’est parti','close')}`;else if(modal==='settings')content=`<h2>Paramètres</h2><p>Sauvegarde automatique : ${auto?'activée':'désactivée'}</p>${btn('Activer / désactiver','autosave')}<p class="muted">La partie reste sur ce navigateur. Pour jouer hors connexion, ouvre d’abord le jeu en ligne et installe-le depuis le menu du navigateur Android.</p>${btn('Fermer','close','light')}`;else if(modal==='confirm')content=`<h2>Nouvelle aventure ?</h2><p>La sauvegarde actuelle sera remplacée lorsque tu commenceras.</p>${btn('Choisir un vélo','selectbike')} ${btn('Annuler','close','light')}`;else if(modal==='finish')content=`<h2>Terminer ce voyage ?</h2><p>Ton score sera calculé avec les découvertes déjà réalisées.</p>${btn('Voir mon score','end')} ${btn('Continuer','close','light')}`;else if(modal==='shop')content=`<h2>Équiper son vélo</h2><div class="shop">${Object.entries(E.equipment).map(([id,e])=>`<button data-buy="${id}" ${g.items.includes(id)||g.money<e.cost?'disabled':''}>${e.name} · ${e.cost} pièces<br><small>${e.desc}${g.items.includes(id)?' · acquis':''}</small></button>`).join('')}</div>${btn('Fermer','close','light')}`;return content?`<div class="modal-back"><section class="modal" role="dialog" aria-modal="true">${content}</section></div>`:'';}
function bind(){document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el.dataset.action));document.querySelectorAll('[data-bike]').forEach(el=>el.onclick=()=>{bike=el.dataset.bike;render();});document.querySelectorAll('[data-select]').forEach(el=>el.onclick=()=>{selected=+el.dataset.select;render();});document.querySelectorAll('[data-place]').forEach(el=>el.onclick=()=>{let [x,y]=el.dataset.place.split(',').map(Number);E.place(g,selected,x,y);selected=0;message='Tuile posée. À toi de choisir ton étape.';render();});document.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>{if(g.phase!=='move')return;if(!E.move(g,el.dataset.move))message='Route inaccessible ou énergie insuffisante. Une pause peut aider.';else message='';render();});document.querySelectorAll('[data-buy]').forEach(el=>el.onclick=()=>{E.buy(g,el.dataset.buy);render();});}
function center(){document.querySelector('.rider')?.parentElement.scrollIntoView({block:'center',inline:'center',behavior:'smooth'});}
function act(a){message='';if(a==='new'){if(g&&!g.done)modal='confirm';else screen='select';}else if(a==='selectbike'){screen='select';modal='';}else if(a==='start'){g=E.makeGame(bike);screen='game';selected=0;}else if(a==='continue')screen='game';else if(a==='home'){screen='home';modal='';}else if(['rules','settings','shop','finish'].includes(a))modal=a;else if(a==='close')modal='';else if(a==='end'){g.done=true;modal='';}else if(a==='autosave'){auto=!auto;localStorage.setItem('velo-auto',auto);}else if(a==='rotate'&&g.phase==='place'){let t=g.hand[selected];if(t)t.rotation=(t.rotation+1)%4;}else if(a==='resolve')E.resolve(g);else if(a==='skip'&&g.phase==='move')E.endTurn(g);else if(['eat','rest','work','food','sleep'].includes(a)){if(!E.recover(g,a))message='Cette action n’est pas disponible avec tes ressources actuelles.';}else if(a==='zoomin')zoom=Math.min(1.6,zoom+.2);else if(a==='zoomout')zoom=Math.max(.6,zoom-.2);render();if(['start','continue','center'].includes(a))center();}
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
